_:n88b0e362ecc94d7b94aeff499f3ceca1b7 sh:message "node is dangling: it is neither source nor target of any edge." ;
    sh:select """
      PREFIX fcm: <https://w3id.org/ogc/hosted/seadots/fcm/>
      SELECT $this ?node WHERE {
        $this fcm:hasNode ?node .
        FILTER NOT EXISTS {
          $this fcm:hasEdge ?edge .
          ?edge fcm:sourceNode|fcm:targetNode ?node .
        }
      } """ .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms true .
